import { generateStars } from '/workspace/master/app/src/shared/galaxy/stars.js';
import { generateSystem } from '/workspace/master/app/src/shared/galaxy/system.js';
import { planetAtmosphereDensity } from '/workspace/master/app/src/shared/galaxy/planets.js';
import { padsForSystem } from '/workspace/master/app/src/shared/world/pads.js';

const SEED = process.env.SCAN_SEED ?? 'DRIFT-SEED-0001';
const stars = generateStars(SEED);
const rows: Array<{ systemId: string; planetId: string; cls: string; density: number; pad: { x: number; y: number; z: number } }> = [];
for (const star of stars) {
  const system = generateSystem(SEED, star.id);
  const planet = system.planets.find((p) => p.landable && p.hasAtmosphere);
  if (!planet) continue;
  const pad = padsForSystem(SEED, system).find((p) => p.planetId === planet.id);
  if (!pad) continue;
  rows.push({
    systemId: system.systemId,
    planetId: planet.id,
    cls: planet.class,
    density: planetAtmosphereDensity(planet),
    pad: pad.pos,
  });
}
rows.sort((a, b) => b.density - a.density);
for (const r of rows) {
  console.log(
    `${r.systemId}  ${r.cls.padEnd(6)}  density=${r.density.toFixed(4)}  pad=(${r.pad.x.toFixed(0)}, ${r.pad.y.toFixed(1)}, ${r.pad.z.toFixed(0)})`,
  );
}
console.log(`total landable+atmospheric pads: ${rows.length}`);

