import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
let png;
try {
  png = require('pngjs');
} catch {
  console.log('no pngjs');
  process.exit(0);
}
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const data = readFileSync(file);
const img = png.PNG.sync.read(data);
const { width: w, height: h } = img;

function regionStats(x0, y0, x1, y1) {
  const x = Math.floor(x0 * w);
  const width = Math.max(1, Math.ceil(x1 * w) - x);
  const yy = Math.floor(y0 * h);
  const height = Math.max(1, Math.ceil(y1 * h) - yy);
  let sum = 0, bright = 0;
  for (let y = yy; y < yy + height; y++) {
    for (let xx = x; xx < x + width; xx++) {
      const i = (y * w + xx) * 4;
      const lum = (img.data[i] + img.data[i + 1] + img.data[i + 2]) / 3;
      sum += lum;
      if (lum > 60) bright++;
    }
  }
  return { mean: sum / (width * height), bright, width, height };
}

const bands = {
  'full top (0..1, 0..0.3)': [0, 0, 1, 0.3],
