  'top-center strip (0.35..0.65, 0.02..0.18)': [0.35, 0.02, 0.65, 0.18],
};
for (const [name, r] of Object.entries(bands)) {
  const s = regionStats(...r);
  console.log(`${name}: mean=${s.mean.toFixed(1)} bright=${s.bright} (${s.width}x${s.height})`);
}
